);
ALTER TABLE app_users ADD COLUMN IF NOT EXISTS name TEXT;                                           -- Lowercased email address. Acts as the primary key. The verified 'email' claim from a magic-links JWT must equal this value for the user to be recognized.
ALTER TABLE app_users ADD COLUMN IF NOT EXISTS display_name TEXT;                                   -- Optional human-friendly display name shown in the Explorer UI.
ALTER TABLE app_users ADD COLUMN IF NOT EXISTS role TEXT;                                           -- App role. One of: 'admin' (full edit/promote rights once Phase 5 lands) or 'member' (read-only today). Word-level promotion to a finer-grained role table can land later as an additive change.
ALTER TABLE app_users ADD COLUMN IF NOT EXISTS notes TEXT;                                          -- Free-text notes — provenance, why-granted, whatever the registry maintainer wants future readers to know.
ALTER TABLE app_users ADD COLUMN IF NOT EXISTS created TIMESTAMPTZ;                                 -- Creation timestamp.
COMMENT ON TABLE app_users IS 'Application users authenticated via magic-links. The Name field is the lowercased email — it is both the primary key and the value that the JWT ''email'' claim resolves against. AppUsers are editing principals (who can sign in and act in the Explorer); they are independent of Owners (who own published artifacts in the registry).';
