);
ALTER TABLE templates ADD COLUMN IF NOT EXISTS name TEXT;                                           -- Composite template identifier. Convention: '<kind>:<owner-version-id>' (e.g. 'axiom:atn.bid/002', 'upgrade:bid/000->bid/002'). Primary key.
