ALTER TABLE templates ADD COLUMN IF NOT EXISTS path TEXT;                                           -- Path to the .jinja2 template file relative to repo root.
ALTER TABLE templates ADD COLUMN IF NOT EXISTS language TEXT;                                       -- Target language. Currently always 'python'.
ALTER TABLE templates ADD COLUMN IF NOT EXISTS status TEXT;                                         -- Template status: 'present' (file exists), 'missing' (declared but not yet scaffolded), 'deprecated'.
