ALTER TABLE templates ADD COLUMN IF NOT EXISTS upgrade_to_type_version TEXT;                        -- When Kind='upgrade' between types: the destination TypeVersion.
ALTER TABLE templates ADD COLUMN IF NOT EXISTS upgrade_from_enum_version TEXT;                      -- When Kind='upgrade' between enums: the source EnumVersion.
ALTER TABLE templates ADD COLUMN IF NOT EXISTS upgrade_to_enum_version TEXT;                        -- When Kind='upgrade' between enums: the destination EnumVersion.
COMMENT ON TABLE templates IS 'Generator templates that implement axiom and upgrade behavior. Runtime generation REQUIRES that every TypeVersion declaring an axiom (or upgrade) has a matching Templates row pointing at the corresponding `.jinja2` file (see runtime_generation/templates/).';
