-- ----------------------------------------------------------------------------
-- CliCommands: The hierarchical surface of the `sema` CLI — every parser node from src/sema/interfaces/cli/. Each row is one subcommand or the root. Parent links form a tree; flags and examples attach via CliFlags.Command and CliExamples.Command. This is descriptive scaffolding (Tier B of ERB-SCAFFOLD-PLAN.md) — the CLI is still implemented in Python, but the rulebook now points at every node.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS cli_commands (
  cli_commands_id                     TEXT                 PRIMARY KEY          -- Primary key (auto-synthesized: CliCommands had no field named 'Id' or ending in 'Id').
);
ALTER TABLE cli_commands ADD COLUMN IF NOT EXISTS name TEXT;                                        -- Fully-qualified command path. Example: 'sema snapshot prepare'. Acts as the primary key.
ALTER TABLE cli_commands ADD COLUMN IF NOT EXISTS parent TEXT;                                      -- FK to the parent CliCommand. NULL for the root 'sema'. Children's Names start with their Parent's Name followed by a single space.
ALTER TABLE cli_commands ADD COLUMN IF NOT EXISTS impl_file TEXT;                                   -- Path (relative to repo root) of the Python file that defines this command's parser/handler.
ALTER TABLE cli_commands ADD COLUMN IF NOT EXISTS summary TEXT;                                     -- Short one-line description, mirroring the argparse `help=` for this subparser.
ALTER TABLE cli_commands ADD COLUMN IF NOT EXISTS description TEXT;                                 -- Longer description, mirroring the argparse `description=` for this subparser. Often spans multiple sentences.
COMMENT ON TABLE cli_commands IS 'The hierarchical surface of the `sema` CLI — every parser node from src/sema/interfaces/cli/. Each row is one subcommand or the root. Parent links form a tree; flags and examples attach via CliFlags.Command and CliExamples.Command. This is descriptive scaffolding (Tier B of ERB-SCAFFOLD-PLAN.md) — the CLI is still implemented in Python, but the rulebook now points at every node.';
COMMENT ON COLUMN cli_commands.cli_commands_id IS 'Primary key (auto-synthesized: CliCommands had no field named ''Id'' or ending in ''Id'').';
COMMENT ON COLUMN cli_commands.name IS 'Fully-qualified command path. Example: ''sema snapshot prepare''. Acts as the primary key.';
COMMENT ON COLUMN cli_commands.parent IS 'FK to the parent CliCommand. NULL for the root ''sema''. Children''s Names start with their Parent''s Name followed by a single space.';
COMMENT ON COLUMN cli_commands.impl_file IS 'Path (relative to repo root) of the Python file that defines this command''s parser/handler.';
COMMENT ON COLUMN cli_commands.summary IS 'Short one-line description, mirroring the argparse `help=` for this subparser.';
COMMENT ON COLUMN cli_commands.description IS 'Longer description, mirroring the argparse `description=` for this subparser. Often spans multiple sentences.';

-- ----------------------------------------------------------------------------
-- CliFlags: Every flag (positional or named) declared on a CliCommand. Name is the compound key Command::FlagName. Kind names a primitive value type; EnumValuesRef points at an Enum when a flag's value is constrained to a rulebook enum (no current flag uses this, but the column is reserved for future use).
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS cli_flags (
  cli_flags_id                        TEXT                 PRIMARY KEY          -- Primary key (auto-synthesized: CliFlags had no field named 'Id' or ending in 'Id').
);
ALTER TABLE cli_flags ADD COLUMN IF NOT EXISTS command TEXT;                                        -- FK to the CliCommands row this flag attaches to.
ALTER TABLE cli_flags ADD COLUMN IF NOT EXISTS flag_name TEXT;                                      -- Flag spelling. Positional args use the bare identifier ('name', 'version'). Named args use the long form including dashes ('--package-name').
ALTER TABLE cli_flags ADD COLUMN IF NOT EXISTS short_name TEXT;                                     -- Short alias if defined ('-p'). NULL for positional args and named-only flags.
ALTER TABLE cli_flags ADD COLUMN IF NOT EXISTS is_positional BOOLEAN;                               -- True when the argparse action is a positional argument. False for named flags.
ALTER TABLE cli_flags ADD COLUMN IF NOT EXISTS kind TEXT;                                           -- Primitive value type. One of 'string', 'bool', 'int', 'path'. Reserved value 'enum' applies when EnumValuesRef is non-null.
ALTER TABLE cli_flags ADD COLUMN IF NOT EXISTS required BOOLEAN;                                    -- True when the flag is mandatory. For positional args this maps to nargs not being '?' or '*'.
ALTER TABLE cli_flags ADD COLUMN IF NOT EXISTS "default" TEXT;                                      -- Stringified default value, or NULL when there is no default.
ALTER TABLE cli_flags ADD COLUMN IF NOT EXISTS description TEXT;                                    -- Short description, taken from argparse `help=` where available.
ALTER TABLE cli_flags ADD COLUMN IF NOT EXISTS enum_values_ref TEXT;                                -- When the flag accepts values constrained to a rulebook Enum, points at the Enum row. NULL otherwise.
COMMENT ON TABLE cli_flags IS 'Every flag (positional or named) declared on a CliCommand. Name is the compound key Command::FlagName. Kind names a primitive value type; EnumValuesRef points at an Enum when a flag''s value is constrained to a rulebook enum (no current flag uses this, but the column is reserved for future use).';
COMMENT ON COLUMN cli_flags.cli_flags_id IS 'Primary key (auto-synthesized: CliFlags had no field named ''Id'' or ending in ''Id'').';
COMMENT ON COLUMN cli_flags.command IS 'FK to the CliCommands row this flag attaches to.';
COMMENT ON COLUMN cli_flags.flag_name IS 'Flag spelling. Positional args use the bare identifier (''name'', ''version''). Named args use the long form including dashes (''--package-name'').';
COMMENT ON COLUMN cli_flags.short_name IS 'Short alias if defined (''-p''). NULL for positional args and named-only flags.';
COMMENT ON COLUMN cli_flags.is_positional IS 'True when the argparse action is a positional argument. False for named flags.';
COMMENT ON COLUMN cli_flags.kind IS 'Primitive value type. One of ''string'', ''bool'', ''int'', ''path''. Reserved value ''enum'' applies when EnumValuesRef is non-null.';
COMMENT ON COLUMN cli_flags.required IS 'True when the flag is mandatory. For positional args this maps to nargs not being ''?'' or ''*''.';
COMMENT ON COLUMN cli_flags."default" IS 'Stringified default value, or NULL when there is no default.';
COMMENT ON COLUMN cli_flags.description IS 'Short description, taken from argparse `help=` where available.';
COMMENT ON COLUMN cli_flags.enum_values_ref IS 'When the flag accepts values constrained to a rulebook Enum, points at the Enum row. NULL otherwise.';

-- ----------------------------------------------------------------------------
-- CliExamples: Concrete example invocations for a CliCommand. Sourced from argparse `epilog=` blocks. Idx preserves listing order. ExpectedExitCode defaults to 0 (success); future rows can document expected-failure examples.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS cli_examples (
  cli_examples_id                     TEXT                 PRIMARY KEY          -- Primary key (auto-synthesized: CliExamples had no field named 'Id' or ending in 'Id').
);
ALTER TABLE cli_examples ADD COLUMN IF NOT EXISTS command TEXT;                                     -- FK to the CliCommands row this example illustrates.
ALTER TABLE cli_examples ADD COLUMN IF NOT EXISTS idx INTEGER;                                      -- 0-indexed ordering of this example within its Command's epilog.
ALTER TABLE cli_examples ADD COLUMN IF NOT EXISTS example_string TEXT;                              -- The full command-line invocation as it would be typed in a terminal.
ALTER TABLE cli_examples ADD COLUMN IF NOT EXISTS description TEXT;                                 -- Optional short note about what this example demonstrates.
ALTER TABLE cli_examples ADD COLUMN IF NOT EXISTS expected_exit_code INTEGER;                       -- POSIX exit code the example is expected to produce. 0 for success.
COMMENT ON TABLE cli_examples IS 'Concrete example invocations for a CliCommand. Sourced from argparse `epilog=` blocks. Idx preserves listing order. ExpectedExitCode defaults to 0 (success); future rows can document expected-failure examples.';
COMMENT ON COLUMN cli_examples.cli_examples_id IS 'Primary key (auto-synthesized: CliExamples had no field named ''Id'' or ending in ''Id'').';
COMMENT ON COLUMN cli_examples.command IS 'FK to the CliCommands row this example illustrates.';
COMMENT ON COLUMN cli_examples.idx IS '0-indexed ordering of this example within its Command''s epilog.';
COMMENT ON COLUMN cli_examples.example_string IS 'The full command-line invocation as it would be typed in a terminal.';
COMMENT ON COLUMN cli_examples.description IS 'Optional short note about what this example demonstrates.';
COMMENT ON COLUMN cli_examples.expected_exit_code IS 'POSIX exit code the example is expected to produce. 0 for success.';

